(()=>{'use strict';const D={"ko": {"briefing": {"title": "11월 27일 아침 브리핑: 금리 다음은 생활의 달력", "intro": "한국은행의 금리 인상 뒤에는 가계와 기업이 감당할 자금 비용이 남는다. 미국의 새 관세안은 아직 의견 수렴 단계이고, 오늘 학교 급식과 대형마트 이용에는 평소와 다른 준비가 필요하다. 11월 27일 아침, 발표와 확정, 전망과 실적을 나눠 주요 뉴스를 정리한다.", "href": "2026-11-27-morning-briefing-ko.html"}, "history": {"title": "유언 한 장은 어떻게 세계의 상이 되었나", "intro": "1895년 11월 27일, 알프레드 노벨은 파리의 스웨덴-노르웨이 클럽에서 세 번째이자 마지막 유언에 서명했다. 그날 노벨상이 수여된 것은 아니다. 유산을 어떤 목적에 쓸지 정한 문서가 남았을 뿐이었다. 첫 시상은 1901년 12월 10일에야 열렸다.", "href": "2026-11-27-nobel-will-ko.html"}}, "en": {"briefing": {"title": "November 27 morning briefing: the calendar behind the rate rise", "intro": "After Korea's rate rise comes the cost households and companies must bear. America's new tariff proposal is still subject to consultation, while school meals and supermarket visits need extra planning today. The morning's news calls for a clear distinction between announcements and decisions, forecasts and results.", "href": "2026-11-27-morning-briefing-en.html"}, "history": {"title": "How a will became a prize for the world", "intro": "On November 27, 1895, Alfred Nobel signed his third and final will at the Swedish-Norwegian Club in Paris. No Nobel Prize was awarded that day. What existed was a document directing the use of his estate. The first prizes were not awarded until December 10, 1901.", "href": "2026-11-27-nobel-will-en.html"}}, "ja": {"briefing": {"title": "11月27日朝のブリーフィング：金利の次に見る生活の予定表", "intro": "韓国の利上げの後には、家計と企業が負担する資金コストが残る。米国の新たな関税案は意見募集の段階であり、今日の学校給食やスーパーの利用には普段と違う準備が要る。発表と決定、予測と実績を分けて朝のニュースを読む。", "href": "2026-11-27-morning-briefing-ja.html"}, "history": {"title": "一通の遺言は、どう世界の賞になったのか", "intro": "1895年11月27日、アルフレッド・ノーベルはパリのスウェーデン・ノルウェー・クラブで、3通目にして最後の遺言に署名した。その日にノーベル賞が授与されたわけではない。遺産の使い道を定めた文書が残されたのだ。初めての授賞は1901年12月10日だった。", "href": "2026-11-27-nobel-will-ja.html"}}, "zh": {"briefing": {"title": "11月27日早间简报：加息之后，看生活日历", "intro": "韩国加息后，家庭和企业仍要面对资金成本。美国的新关税方案还在征求意见，今天的学校供餐和超市购物也需要额外准备。读早间新闻，要把宣布与决定、预测与实绩分开。", "href": "2026-11-27-morning-briefing-zh.html"}, "history": {"title": "一份遗嘱如何成为面向世界的奖项", "intro": "1895年11月27日，阿尔弗雷德·诺贝尔在巴黎的瑞典挪威俱乐部签署了第三份，也是最后一份遗嘱。那天并没有颁发诺贝尔奖，留下的只是一份规定遗产用途的文件。首次颁奖直到1901年12月10日才举行。", "href": "2026-11-27-nobel-will-zh.html"}}, "es": {"briefing": {"title": "Resumen del 27 de noviembre: tras el tipo, el calendario cotidiano", "intro": "Tras la subida de tipos en Corea llega el coste para hogares y empresas. La nueva propuesta arancelaria estadounidense sigue en consulta, mientras que los comedores escolares y las compras requieren preparativos distintos hoy. Conviene separar anuncios de decisiones y previsiones de resultados.", "href": "2026-11-27-morning-briefing-es.html"}, "history": {"title": "Cómo un testamento se convirtió en un premio para el mundo", "intro": "El 27 de noviembre de 1895, Alfred Nobel firmó su tercer y último testamento en el Club Sueco-Noruego de París. Aquel día no se entregó ningún Premio Nobel. Existía un documento que indicaba cómo emplear su patrimonio. Los primeros premios no llegaron hasta el 10 de diciembre de 1901.", "href": "2026-11-27-nobel-will-es.html"}}};let last='';function sync(){const l=document.documentElement.dataset.lang||'ko';if(last===l)return;last=l;const q=D[l]||D.en;for(const [id,k] of [['daily-news-briefing','briefing'],['president-series-feature','history']]){const e=document.getElementById(id);if(!e)continue;const a=e.querySelector('h2 a');if(a){a.textContent=q[k].title;a.href=q[k].href}e.querySelectorAll('a').forEach(a=>{a.href=q[k].href;if(!a.closest('h2'))a.textContent=({ko:'전문 읽기 →',en:'Read full article →',ja:'全文を読む →',zh:'阅读全文 →',es:'Leer texto completo →'})[l]||'Read full article →';});const p=e.querySelector('p');if(p)p.textContent=q[k].intro;}}new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['data-lang']});sync();})();